agent_detail.agent_sql:
SELECT DISTINCT ?molecule_id WHERE {
  ?b a <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Bond> ;
     <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Bond/bond_type> "#" ;
     <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Bond/molecule_id> ?molecule_id .
  ?m a <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Molecule> ;
     <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Molecule/molecule_id> ?molecule_id ;
     <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Molecule/label> "+" .
}

SELECT ?bond_type (COUNT(*) AS ?n)
WHERE {
  ?b a <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Bond> ;
     <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Bond/bond_type> ?bond_type .
}
GROUP BY ?bond_type
ORDER BY DESC(?n)
LIMIT 1

SELECT (AVG(?cnt) AS ?avgSingleBonds)
WHERE {
  {
    SELECT ?m (COUNT(?b) AS ?cnt)
    WHERE {
      ?mol a <http://bird-bird_toxicology-ontology-20260806-113341/ontology/vkg-bird_toxicology/Molecule> ;
           <http://bird-bird_toxicology-ontology-20260806-113341/ontology/vkg-bird_toxicology/Molecule/molecule_id> ?m ;
           <http://bird-bird_toxicology-ontology-20260806-113341/ontology/vkg-bird_toxicology/Molecule/label> ?lab .
      FILTER(?lab = "+")
      ?b a <http://bird-bird_toxicology-ontology-20260806-113341/ontology/vkg-bird_toxicology/Bond> ;
         <http://bird-bird_toxicology-ontology-20260806-113341/ontology/vkg-bird_toxicology/Bond/molecule_id> ?m ;
         <http://bird-bird_toxicology-ontology-20260806-113341/ontology/vkg-bird_toxicology/Bond/bond_type> ?bt .
      FILTER(?bt = "-")
    }
    GROUP BY ?m
  }
}

SELECT DISTINCT ?element WHERE {
  ?conn a <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Connected> ;
        <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Connected/bond_id> "TR004_8_9" ;
        <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Connected/atom_id> ?atomId .
  ?atom a <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Atom> ;
        <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Atom/atom_id> ?atomId ;
        <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Atom/element> ?element .
}

SELECT ?label (COUNT(*) AS ?n) WHERE {
  ?atom a <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Atom> ;
        <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Atom/element> ?element ;
        <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Atom/molecule_id> ?mid .
  FILTER(LCASE(?element) = "h")
  ?mol a <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Molecule> ;
       <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Molecule/molecule_id> ?mid ;
       <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Molecule/label> ?label .
}
GROUP BY ?label
ORDER BY DESC(?n)
LIMIT 1

SELECT (AVG(?oxyCount) AS ?avgOxygenAtoms)
WHERE {
  {
    SELECT ?m (COUNT(?a) AS ?oxyCount)
    WHERE {
      {
        SELECT DISTINCT ?m
        WHERE {
          ?b a <http://bird-bird_toxicology-ontology-20260806-113341/ontology/vkg-bird_toxicology/Bond> ;
             <http://bird-bird_toxicology-ontology-20260806-113341/ontology/vkg-bird_toxicology/Bond/bond_type> "-" ;
             <http://bird-bird_toxicology-ontology-20260806-113341/ontology/vkg-bird_toxicology/Bond/molecule_id> ?m .
        }
      }
      OPTIONAL {
        ?a a <http://bird-bird_toxicology-ontology-20260806-113341/ontology/vkg-bird_toxicology/Atom> ;
           <http://bird-bird_toxicology-ontology-20260806-113341/ontology/vkg-bird_toxicology/Atom/molecule_id> ?m ;
           <http://bird-bird_toxicology-ontology-20260806-113341/ontology/vkg-bird_toxicology/Atom/element> "o" .
      }
    }
    GROUP BY ?m
  }
}

SELECT ?element (COUNT(*) AS ?cnt) WHERE {
  ?a a <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Atom> ;
     <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Atom/element> ?element ;
     <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Atom/molecule_id> ?molId .
  ?m a <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Molecule> ;
     <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Molecule/molecule_id> ?molId ;
     <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Molecule/label> ?label .
  FILTER(?label = "-")
}
GROUP BY ?element
ORDER BY ?cnt
LIMIT 1

SELECT ?bond_type WHERE {
  ?connected <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Connected/atom_id> "TR004_8" ;
             <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Connected/atom_id2> "TR004_20" ;
             <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Connected/bond_id> ?bondId .
  ?bond a <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Bond> ;
        <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Bond/bond_id> ?bondId ;
        <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Bond/bond_type> ?bond_type .
}

SELECT (COUNT(?a) AS ?n) WHERE {
  ?a a <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Atom> ;
     <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Atom/element> ?el ;
     <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Atom/molecule_id> ?mid .
  FILTER(LCASE(?el) IN ("i", "s"))
