     <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Bond/molecule_id> ?mid ;
     <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Bond/bond_type> ?bt .
  FILTER(?bt = "-")
}

SELECT DISTINCT ?element WHERE {
  ?a a <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Atom> ;
     <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Atom/molecule_id> "TR000" ;
     <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Atom/element> ?element .
}
ORDER BY ?element
LIMIT 3

SELECT ?element ?label WHERE {
  ?m a <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Molecule> ;
     <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Molecule/molecule_id> "TR060" ;
     <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Molecule/label> ?label .
  ?a a <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Atom> ;
     <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Atom/molecule_id> "TR060" ;
     <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Atom/element> ?element .
}

SELECT ?bond_type ?label (COUNT(*) AS ?bondCount)
WHERE {
  ?m a <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Molecule> ;
     <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Molecule/molecule_id> "TR010" ;
     <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Molecule/label> ?label .
  ?b a <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Bond> ;
     <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Bond/molecule_id> "TR010" ;
     <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Bond/bond_type> ?bond_type .
}
GROUP BY ?bond_type ?label
ORDER BY DESC(?bondCount)
LIMIT 1

SELECT (ROUND((?doubleCount * 100000.0) / ?total) / 100000.0 AS ?percentage)
WHERE {
  {
    SELECT (COUNT(?b) AS ?total) (SUM(IF(?bt = "=", 1, 0)) AS ?doubleCount)
    WHERE {
      ?b a <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Bond> ;
         <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Bond/molecule_id> "TR008" ;
         <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Bond/bond_type> ?bt .
    }
  }
}

