  ?m a <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Molecule> ;
     <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Molecule/molecule_id> ?molecule_id ;
     <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Molecule/label> ?label .
  FILTER(?label = "-")
  ?b a <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Bond> ;
     <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Bond/molecule_id> ?molecule_id ;
     <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Bond/bond_type> ?bond_type .
  FILTER(?bond_type = "-")
}
