  ?bond a <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Bond> ;
        <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Bond/molecule_id> "TR009" ;
        <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Bond/bond_id> ?bondId .
  ?conn a <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Connected> ;
        <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Connected/bond_id> ?bondId .
  { ?conn <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Connected/atom_id> "TR009_12" }
  UNION
  { ?conn <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Connected/atom_id2> "TR009_12" }
