SELECT ?bond_type ?atom_id ?atom_id2 WHERE {
  ?b a <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Bond> ;
     <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Bond/bond_id> "TR001_6_9" ;
     <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Bond/bond_type> ?bond_type .
  ?c a <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Connected> ;
     <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Connected/bond_id> "TR001_6_9" ;
     <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Connected/atom_id> ?atom_id ;
     <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Connected/atom_id2> ?atom_id2 .
}

SELECT (COUNT(?c) AS ?n) WHERE {
  ?c a <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Connected> ;
     <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Connected/atom_id> ?aid .
  FILTER(?aid = "19")
}

SELECT (100.0 * xsd:decimal(?carc) / xsd:decimal(?total) AS ?pct)
WHERE {
  {
    SELECT (COUNT(DISTINCT ?m) AS ?total)
    WHERE {
      ?b a <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Bond> ;
         <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Bond/bond_type> "#" ;
         <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Bond/hasMolecule> ?m .
    }
  }
  {
    SELECT (COUNT(DISTINCT ?m2) AS ?carc)
    WHERE {
      ?b2 a <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Bond> ;
          <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Bond/bond_type> "#" ;
          <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Bond/hasMolecule> ?m2 .
      ?m2 a <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Molecule> ;
          <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Molecule/label> "+" .
    }
  }
}

SELECT ?element WHERE {
  ?atom a <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Atom> ;
        <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Atom/molecule_id> "TR004" ;
        <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Atom/element> ?element .
}

SELECT ((xsd:decimal(?noFcount) * 100.0) / xsd:decimal(?totalcount) AS ?pct)
WHERE {
  {
    SELECT (COUNT(DISTINCT ?m) AS ?totalcount) WHERE {
      ?m a <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Molecule> ;
         <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Molecule/label> "+" .
    }
  }
  {
    SELECT (COUNT(DISTINCT ?m2) AS ?noFcount) WHERE {
      ?m2 a <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Molecule> ;
          <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Molecule/label> "+" .
      FILTER NOT EXISTS {
        ?a <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Atom/hasMolecule> ?m2 ;
           <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Atom/element> "f" .
      }
    }
  }
}

SELECT (100.0 * xsd:decimal(?carbonCount) / xsd:decimal(?totalCount) AS ?percentage)
WHERE {
  {
    SELECT (COUNT(?a) AS ?carbonCount) WHERE {
      ?a a <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Atom> ;
         <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Atom/element> ?el ;
         <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Atom/molecule_id> ?mid .
      FILTER(?el = "c")
      FILTER EXISTS {
        ?b a <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Bond> ;
           <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Bond/molecule_id> ?mid ;
           <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Bond/bond_type> "=" .
      }
    }
  }
  {
    SELECT (COUNT(?a2) AS ?totalCount) WHERE {
      ?a2 a <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Atom> ;
          <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Atom/molecule_id> ?mid2 .
      FILTER EXISTS {
        ?b2 a <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Bond> ;
            <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Bond/molecule_id> ?mid2 ;
            <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Bond/bond_type> "=" .
      }
    }
  }
}

SELECT (ROUND((xsd:decimal(?carc)*100.0/xsd:decimal(?total))*1000)/1000 AS ?percentage)
WHERE {
  {
    SELECT (COUNT(?m) AS ?total) WHERE {
      ?m a <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Molecule> .
    }
  }
  {
    SELECT (COUNT(?m2) AS ?carc) WHERE {
      ?m2 a <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Molecule> ;
          <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Molecule/label> ?l .
      FILTER(?l = "+")
    }
  }
}

SELECT ?molecule_id ?label (COUNT(?bond) AS ?doubleBondCount)
WHERE {
  ?bond a <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Bond> ;
        <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Bond/molecule_id> ?molecule_id ;
        <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Bond/bond_type> ?bt .
  FILTER(?bt = "=")
  ?m a <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Molecule> ;
     <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Molecule/molecule_id> ?molecule_id ;
     <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Molecule/label> ?label .
}
GROUP BY ?molecule_id ?label
ORDER BY DESC(?doubleBondCount)
LIMIT 1

SELECT DISTINCT ?element WHERE {
  ?a a <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Atom> ;
     <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Atom/atom_id> ?aid ;
     <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Atom/element> ?element .
  FILTER NOT EXISTS {
    ?c1 a <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Connected> ;
        <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Connected/atom_id> ?aid .
  }
  FILTER NOT EXISTS {
    ?c2 a <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Connected> ;
        <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Connected/atom_id2> ?aid .
  }
}

SELECT DISTINCT ?bond_id WHERE {
  ?c a <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Connected> ;
     <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Connected/atom_id> ?a1id ;
     <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Connected/atom_id2> ?a2id ;
     <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Connected/bond_id> ?bond_id .
  ?a1 a <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Atom> ;
      <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Atom/atom_id> ?a1id ;
      <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Atom/element> ?e1 .
  ?a2 a <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Atom> ;
      <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Atom/atom_id> ?a2id ;
      <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Atom/element> ?e2 .
  FILTER(
    (LCASE(?e1) = "p" && LCASE(?e2) = "n") ||
    (LCASE(?e1) = "n" && LCASE(?e2) = "p")
  )
}

SELECT (AVG(?cnt) AS ?avgBonds) WHERE {
  {
    SELECT ?aid (COUNT(?conn) AS ?cnt) WHERE {
      ?atom a <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Atom> ;
            <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Atom/element> "i" ;
            <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Atom/atom_id> ?aid .
      ?conn a <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Connected> ;
            <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Connected/atom_id> ?aid .
    }
    GROUP BY ?aid
  }
}

SELECT ?atom_id ?atom_id2 WHERE {
  ?bond a <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Bond> ;
        <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Bond/molecule_id> "TR041" ;
        <http://bird-bird_toxicology-ontology-20260805-014648/ontology/vkg-bird_toxicology/Bond/bond_type> "#" ;
